style.css:
@-moz-document domain("youtube.com") {
/* Variabel Warna Utama YouTube */
  html[dark], [dark], html {
    --yt-spec-base-background: #0a0a0a !important;         /* Latar belakang utama (Hitam) */
    --yt-spec-raised-background: #141414 !important;       /* Card / Sidebar / Dropdown */
    --yt-spec-menu-background: #1f1f1f !important;         /* Menu Popup */
    --yt-spec-text-primary: #ffffff !important;            /* Teks utama (Putih) */
    --yt-spec-text-secondary: #cccccc !important;          /* Teks sekunder (Putih pudar) */
    --yt-spec-brand-icon-leading: #e60000 !important;       /* Logo YT (Merah) */
    --yt-spec-static-brand-red: #e60000 !important;         /* Aksen Merah YT */
  }

  /* Warna Header / Navigation Bar Atas */
  #masthead-container.ytd-app,
  ytd-app {
    background-color: #0a0a0a !important;
  }

  /* Warna Teks Umum */
  body, yt-formatted-string, span, div {
    color: #ffffff !important;
  }

  /* Semua Link/Tautan menjadi Warna Emas */
  a, 
  a.yt-simple-endpoint,
  #video-title,
  .yt-core-attributed-string__link {
    color: #ffd700 !important;
  }

  /* Efek Hover Link (Memerah saat diarahkan kursor) */
  a:hover, 
  #video-title:hover {
    color: #e60000 !important;
  }

  /* Tombol Utama / Aksen Merah */
  ytd-button-renderer.style-primary[is-paper-button] {
    background-color: #e60000 !important;
    color: #ffffff !important;
  }
}

@-moz-document domain("music.youtube.com") {
/* Variabel Warna Utama YouTube Music */
  ytmusic-app {
    --ytmusic-background: #0a0a0a !important;               /* Latar belakang utama (Hitam) */
    --ytmusic-player-bar-background: #141414 !important;     /* Player Bar bawah */
    --ytmusic-search-background: #1f1f1f !important;         /* Kolom pencarian */
    --ytmusic-color-primary: #ffffff !important;             /* Teks utama (Putih) */
    --ytmusic-color-secondary: #cccccc !important;           /* Teks sekunder */
  }

  /* Warna Header dan Navigasi */
  ytmusic-nav-bar {
    background-color: #0a0a0a !important;
  }

  /* Semua Link/Judul Musik/Artis menjadi Warna Emas */
  a, 
  .title.ytmusic-carousel-shelf-basic-header-renderer,
  ytmusic-two-row-item-renderer .title a,
  ytmusic-list-item-renderer .title a {
    color: #ffd700 !important;
  }

  /* Efek Hover Link pada YT Music */
  a:hover {
    color: #e60000 !important;
  }

  /* Bar Pemutar Musik & Garis Aksen */
  ytmusic-player-bar {
    border-top: 2px solid #e60000 !important;
  }

  /* Progress Bar Lagu (Aksen Merah) */
  #progress-bar.ytmusic-player-bar {
    --paper-slider-active-color: #e60000 !important;
    --paper-slider-knob-color: #e60000 !important;
  }
}
